  "ch7.model.title": "Frame timeline: useLayoutEffect vs. useEffect",
  "ch7.model.how": "Drag the Render, useLayoutEffect, and useEffect sliders, and toggle whether tooltip repositioning runs in useLayoutEffect or useEffect. Watch the 16.67 ms 60 Hz frame line and the flicker indicator.",
  "ch7.ctl.render": "Render time",
